BATCH = [[cents, bps] for cents in range(1, 2_001) for bps in (825, 1_000, 2_500)]
BATCH += [[-cents, bps] for cents in range(1, 201) for bps in (825, 1_000, 2_500)]


def node_float_rounding(batch):
